import{_ as a,c as t,o as r,ae as l}from"./chunks/framework.CDAOyxyO.js";const d=JSON.parse('{"title":"Join","description":"","frontmatter":{},"headers":[],"relativePath":"useful/join/index.md","filePath":"useful/join/index.md"}'),i={name:"useful/join/index.md"};function n(o,e,s,u,p,h){return r(),t("div",null,e[0]||(e[0]=[l('<h1 id="join" tabindex="-1">Join <a class="header-anchor" href="#join" aria-label="Permalink to &quot;Join&quot;">​</a></h1><h2 id="списки-рассылок" tabindex="-1">Списки рассылок <a class="header-anchor" href="#списки-рассылок" aria-label="Permalink to &quot;Списки рассылок&quot;">​</a></h2><p>Перед началом рекомендуется подписаться и ознакомиться с архивом рассылок, так как вы далеко не первый человек, который решил пройти данный процесс. Велика вероятность, что ответы на ваши вопросы уже содержатся в предыдущих письмах.</p><blockquote><ul><li><p><a href="https://lists.altlinux.org/mailman/listinfo/devel-newbies" target="_blank" rel="noreferrer">devel-newbies</a> - Эта рассылка может рассматриваться как отправная точка для новичков. В списке devel-newbies участники ALT Linux Team оказывают поддержку начинающим мейнтейнерам, отвечают на часто задаваемые вопросы, связанные с разработкой и сборкой пакетов. Кроме того, именно здесь можно выразить желание пройти join и найти себе ментора.</p></li><li><p><a href="https://lists.altlinux.org/mailman/listinfo/community" target="_blank" rel="noreferrer">Community</a> - Нововсти и обсуждения в сообществе.</p></li><li><p><a href="https://lists.altlinux.org/mailman/listinfo/sisyphus" target="_blank" rel="noreferrer">Sisyphus</a> - Обсуждения вопросов, связанных с Sisyphus</p></li><li><p><a href="https://lists.altlinux.org/mailman/listinfo/devel" target="_blank" rel="noreferrer">Devel</a> - Список рассылки ALT Linux Team, предназначенный для обсуждения вопросов разработки.</p></li></ul></blockquote><h2 id="наити-пакет-для-сборки" tabindex="-1">Найти пакет для сборки? <a class="header-anchor" href="#наити-пакет-для-сборки" aria-label="Permalink to &quot;Найти пакет для сборки?&quot;">​</a></h2><blockquote><ul><li><p><a href="https://bugzilla.altlinux.org/buglist.cgi?bug_status=NEW&amp;bug_status=ASSIGNED&amp;bug_status=REOPENED&amp;list_id=130428&amp;product=New%2Fproposed%20packages&amp;query_format=advanced" target="_blank" rel="noreferrer">Список запросов на добавление новых пакетов в Sisyphus</a></p></li><li><p><a href="https://watch.altlinux.org/pub/watch/by-leader/%40nobody.txt" target="_blank" rel="noreferrer">Список пакетов без сопровождающего</a></p></li><li><p><a href="https://git.altlinux.org/beehive/logs/Sisyphus-x86_64/latest/error/" target="_blank" rel="noreferrer">Список пакетов, сборка которых в данный момент не работает, нуждаются в починке</a></p></li><li><p><a href="https://forum.altlinux.org/index.php?topic=838.960" target="_blank" rel="noreferrer">Каких пакетов не хватает в Sisyphus - forum.altlinux.org</a></p></li></ul></blockquote>',6)]))}const _=a(i,[["render",n]]);export{d as __pageData,_ as default};
